// SPDX-License-Identifier: GPL-2.0
use kernel::prelude::*;

module! {
    type: RustMinimal,
    name: "rust_minimal",
    authors: ["Rust for Linux Contributors"],
    description: "Rust minimal sample",
    license: "GPL",
}

struct RustMinimal {
    numbers: KVec<i32>,
}

impl kernel::Module for RustMinimal {
    fn init(_module: &'static ThisModule) -> Result<Self> {
        pr_info!("Rust minimal sample (init)\n");
        let mut numbers = KVec::new();
        numbers.push(72, GFP_KERNEL)?;
        numbers.push(108, GFP_KERNEL)?;
        numbers.push(200, GFP_KERNEL)?;
        Ok(RustMinimal { numbers })
    }
}

impl Drop for RustMinimal {
    fn drop(&mut self) {
        pr_info!("My numbers are {:?}\n", self.numbers);
        pr_info!("Rust minimal sample (exit)\n");
    }
}

const MAX_ERRNO: i32 = 4095;

fn try_from_errno(errno: i32) -> Option<Error> {
    if errno < -MAX_ERRNO || errno >= 0 {
        return None;
    }
    Some(Error(NonZeroI32::new(errno).unwrap()))
}

fn from_errno(errno: i32) -> Error {
    match try_from_errno(errno) {
        Some(e) => e,
        None => {
            pr_warn!("out of range errno: {}\n", errno);
            EINVAL
        }
    }
}

pub fn to_result(err: i32) -> Result {
    if err < 0 {
        Err(from_errno(err))
    } else {
        Ok(())
    }
}

use kernel::sync::Mutex;

struct Example {
    a: u32,
    b: u32,
}

fn example(m: &Mutex<Example>) {
    let mut guard = m.lock();
    guard.a += 10;
    guard.b += 20;
} // guard dropped here: mutex_unlock()

struct Counter {
    value: u32,
}

fn bump(m: &Mutex<Counter>, r: &mut UserSliceReader) -> Result {
    let mut g = m.lock();
    let delta = r.read::<u32>()?;
    g.value = g.value.checked_add(delta).ok_or(EOVERFLOW)?;
    Ok(())
}

use kernel::sync::{new_mutex, Mutex};

struct Inner {
    a: u32,
    b: u32,
}

#[pin_data]
struct Example {
    c: u32,
    #[pin]
    d: Mutex<Inner>,
}

impl Example {
    fn new() -> impl PinInit<Self> {
        pin_init!(Self {
            c: 10,
            d <- new_mutex!(Inner { a: 20, b: 30 }),
        })
    }
}

fn make() -> Result {
    let e = KBox::pin_init(Example::new(), GFP_KERNEL)?;
    assert_eq!(e.c, 10);
    assert_eq!(e.d.lock().a, 20);
    Ok(())
}

const VTABLE: bindings::file_operations = bindings::file_operations {
    open: Some(Self::open),
    release: Some(Self::release),
    read_iter: if T::HAS_READ_ITER { Some(Self::read_iter) } else { None },
    unlocked_ioctl: if T::HAS_IOCTL { Some(Self::ioctl) } else { None },
    // ...more optional entries...
    owner: this_module::<T::OwnerModule>().as_ptr(),
    ..pin_init::zeroed()
};

unsafe extern "C" fn open(inode: *mut bindings::inode, raw_file: *mut bindings::file) -> c_int {
    // ...generic_file_open, recover &MiscDeviceRegistration<T> from private_data...
    let ptr = match T::open(file, misc) {
        Ok(ptr) => ptr,
        Err(err) => return err.to_errno(),
    };
    // SAFETY: The open call of a file can access the private data.
    unsafe { (*raw_file).private_data = ptr.into_foreign() };
    0
}

fn ioctl(me: Pin<&RustMiscDevice>, _file: &File, cmd: u32, arg: usize) -> Result<isize> {
    let arg = UserPtr::from_addr(arg);
    let size = _IOC_SIZE(cmd);
    match cmd {
        RUST_MISC_DEV_GET_VALUE => me.get_value(UserSlice::new(arg, size).writer())?,
        RUST_MISC_DEV_SET_VALUE => me.set_value(UserSlice::new(arg, size).reader())?,
        RUST_MISC_DEV_HELLO => me.hello()?,
        _ => return Err(ENOTTY),
    };
    Ok(0)
}
